def check_deck(values):
    """Check if a deck satisfies the condition."""
    n = len(values)
    # For each pair, check if AM equals GM of some sub-collection
    for i in range(n):
        for j in range(i+1, n):
            am = Fraction(values[i] + values[j], 2)
            found = False
            # Try all non-empty sub-collections
            for mask in range(1, 1 << n):
                subset = [values[k] for k in range(n) if mask & (1 << k)]
                s = len(subset)
                # GM^s = product of subset
                # AM^s = product of subset?
                prod = 1
                for x in subset:
                    prod *= x
                if am ** s == prod:
                    found = True
                    break
            if not found:
                return False
    return True

