from fractions import Fraction
import itertools

def check_deck(values):
    n = len(values)
    for i in range(n):
        for j in range(i+1, n):
            am = Fraction(values[i] + values[j], 2)
            found = False
            for mask in range(1, 1 << n):
                s = bin(mask).count('1')
                prod = 1
                for k in range(n):
                    if mask & (1 << k):
                        prod *= values[k]
                if am ** s == prod:
                    found = True
                    break
            if not found:
                return False
    return True

# n=4, odd values up to 60
print("=== n=4, odd values up to 60 ===")
odds = list(range(1, 62, 2))
count = 0
for combo in itertools.combinations_with_replacement(odds, 4):
    if len(set(combo)) == 1:
        continue
    if check_deck(list(combo)):
        print(f"  Found: {combo}")
        count += 1
print(f"  Total: {count}")

# n=5, odd values up to 30
print("\n=== n=5, odd values up to 30 ===")
odds5 = list(range(1, 32, 2))
count5 = 0
for combo in itertools.combinations_with_replacement(odds5, 5):
    if len(set(combo)) == 1:
        continue
    if check_deck(list(combo)):
        print(f"  Found: {combo}")
        count5 += 1
print(f"  Total: {count5}")
